import {BODY,createProgressStore} from './progress.js';
import {chart} from './progress-ui.js';
import {createGoalsStore,goalsOn} from './goals.js';
import {buildDashboard} from './dashboard.js';
import {recipeId} from './recipe-id.js';
import {NUTRITION_STORAGE_KEY} from './app-storage.js';
import {validDiaryEntry} from './diary-entry.js';
import {navigate} from './navigation.js';
import {storageErrorMessage} from './storage-health.js';
const $=id=>document.getElementById(id),el=(tag,text)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;return e;};
const format=new Intl.NumberFormat('pl-PL',{maximumFractionDigits:1}),num=v=>v===null?'brak danych':format.format(v);
const labels={kcal:'kcal',protein:'Białko',fat:'Tłuszcz',carbs:'Węglowodany'};
function localDay(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function readNumber(field){const raw=field.value.trim();if(!raw)return undefined;if(!/^\d+(?:[.,]\d+)?$/.test(raw))throw new Error('Podaj poprawną liczbę, np. 80,5.');return Number(raw.replace(',','.'));}
export function initDashboard(){
 const goals=createGoalsStore(),progress=createProgressStore();let revision=0,busy=false;
 const status=text=>$('goals-status').textContent=text;
 const form=$('goals-form');form.elements.effectiveFrom.value=localDay();
 for(const [key,label]of Object.entries(BODY)){const labelNode=el('label',label+' — cel (cm)'),input=el('input');input.id='goal-body-'+key;input.name='body-'+key;input.type='text';input.inputMode='decimal';input.maxLength=20;labelNode.htmlFor=input.id;$('goals-body-fields').append(labelNode,input);}
 form.onsubmit=async event=>{event.preventDefault();if(busy)return;busy=true;try{const row={id:recipeId(),effectiveFrom:form.elements.effectiveFrom.value,nutrition:{},weight:{},body:{}};for(const key of Object.keys(labels)){const v=readNumber(form.elements.namedItem(key));if(v!==undefined)row.nutrition[key]=v;}const kg=readNumber(form.elements.namedItem('kg'));if(kg!==undefined)row.weight.kg=kg;if(form.elements.targetDate.value)row.weight.targetDate=form.elements.targetDate.value;for(const key of Object.keys(BODY)){const v=readNumber(form.elements.namedItem('body-'+key));if(v!==undefined)row.body[key]=v;}
  const existing=(await goals.read()).some(r=>r.effectiveFrom===row.effectiveFrom);let replaceToday=false;if(existing&&row.effectiveFrom===localDay()){if(!confirm('Zastąpić dzisiejsze cele? Wpłynie to na podsumowanie dzisiejszego dnia. Starsze okresy pozostaną bez zmian.'))return;replaceToday=true;}await goals.add(row,{replaceToday});status('Zapisano nowy okres celów. Poprzednie okresy pozostają w historii.');await refresh();
 }catch(e){status(storageErrorMessage(e));}finally{busy=false;}};
 $('goals-copy').onclick=async()=>{try{const row=goalsOn(await goals.read(),form.elements.effectiveFrom.value);for(const key of Object.keys(labels))form.elements.namedItem(key).value=row?.nutrition[key]??'';form.elements.kg.value=row?.weight.kg??'';form.elements.targetDate.value=row?.weight.targetDate??'';for(const key of Object.keys(BODY))form.elements.namedItem('body-'+key).value=row?.body[key]??'';status('Wczytano cele obowiązujące w wybranym dniu. Zapis tworzy nowy okres.');}catch(e){status(storageErrorMessage(e));}};
 async function refresh(){const tick=++revision;try{
  const periods=await goals.read();if(tick!==revision)return;
  const history=$('goals-history');history.replaceChildren();for(let i=periods.length-1;i>=0;i--){const r=periods[i];history.append(el('p',`Od ${r.effectiveFrom}${periods[i+1]?' do dnia przed '+periods[i+1].effectiveFrom:''}: `+[...Object.entries(r.nutrition).map(([k,v])=>`${labels[k]} ${num(v)}${k==='kcal'?'':' g'}`),...(r.weight.kg?[`Masa ${num(r.weight.kg)} kg${r.weight.targetDate?' do '+r.weight.targetDate:''}`]:[]),...Object.entries(r.body).map(([k,v])=>`${BODY[k]} ${num(v)} cm`)].join(' · ')+(Object.keys(r.nutrition).length||r.weight.kg||Object.keys(r.body).length?'':'Brak celów')));}if(!periods.length)history.textContent='Nie ustawiono jeszcze celów.';
  if(document.documentElement.dataset.route!=='dziennik')return;
